<!-- 文件作用：提供本人微信消息偏好和明确授权入口，不把接收开关伪装成永久订阅权限。 -->
<template><AppShell title="微信提醒" back><view class="subscription-intro"><view class="subscription-intro-icon"><Icon name="bell" :size="27"/></view><view class="subscription-intro-copy"><text class="subscription-intro-title">重要进展，微信及时提醒</text><text class="subscription-muted">订阅不影响正常使用</text></view></view><view v-if="error" class="error-box subscription-error"><text>{{error}}</text><button class="text-btn" :disabled="loading" @click="load">重新加载</button></view><EmptyState v-if="!state.user&&!loading" title="登录后设置微信提醒" detail="订单和申请消息会保留在站内消息中心。" icon="bell"><button class="text-btn" @click="go('/pages/account/login?next='+encodeURIComponent('/pages/account/subscriptions'))">登录</button></EmptyState><template v-else-if="overview"><text v-if="!overview.enabled" class="subscription-notice">平台暂未启用微信提醒，站内消息正常保留。</text><text class="subscription-section-title">选择需要的消息</text><view v-for="item in overview.scenes" :key="item.scene" class="subscription-row"><view class="subscription-row-copy"><text class="subscription-label">{{item.label}}</text><text class="subscription-muted">{{item.description}}</text><text v-if="!item.available" class="subscription-unavailable">{{item.reason||'该提醒暂不可订阅'}}</text><label v-else class="subscription-choice"><checkbox :checked="selected.includes(item.scene)" :disabled="busy" :color="accent" @click="toggleSelection(item.scene)"/><text>本次申请</text></label></view><NativeSwitch :checked="item.preference!==false" :disabled="busy" :color="accent" @change="setPreference(item.scene,$event.detail.value)"/></view><button class="btn subscription-authorize" :disabled="busy||loading||!selectedCandidates.length" @click="subscribe">{{busy?'正在处理…':'接收微信提醒'}}</button><text class="subscription-footnote">{{overview.authorization_note||'一次订阅对应一次提醒，微信授权不等于永久通知权限。'}}</text><text class="subscription-footnote">接收开关只控制平台偏好；每次最多申请三个不同模板。拒绝不影响发布、下单。</text></template><view v-else-if="loading" class="loading-line">正在读取提醒设置…</view></AppShell></template>
<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {onShow,onHide,onUnload} from '@dcloudio/uni-app'
import AppShell from '../../components/AppShell.vue'
import EmptyState from '../../components/EmptyState.vue'
import Icon from '../../components/Icon.vue'
import NativeSwitch from '../../components/NativeSwitch.vue'
import {state,init,sessionRevision,game} from '../../lib/store'
import {token,errorMessage} from '../../api/client'
import {getSubscriptions,updateSubscriptionPreferences,recordSubscriptionAuthorization} from '../../api/subscriptions.api'
import {subscriptionCandidates,requestSubscriptionFromGesture,wechatSubscribeAPI} from '../../lib/subscriptions'
import {go,notify} from '../../lib/format'
import {useNativePageRefresh} from '../../lib/native-page-refresh'
import type {SubscriptionOverview,SubscriptionScene} from '../../types/subscriptions'
const overview=ref<SubscriptionOverview|null>(null),selected=ref<SubscriptionScene[]>([]),loading=ref(false),busy=ref(false),error=ref('')
const accent=computed(()=>game.value.primary_color),selectedCandidates=computed(()=>subscriptionCandidates(overview.value,selected.value))
let visible=false,disposed=false,readVersion=0,operation=0
/** 捕获令牌和账号修订，过期请求不能写入新身份。 */
function session(){return{id:state.user?.id,token:token(),revision:sessionRevision()}}
/** 原生授权暂时隐藏后允许记录原账号回包，但不能跨账号。 */
function same(owner:ReturnType<typeof session>){return !disposed&&!!owner.id&&owner.id===state.user?.id&&owner.token===token()&&owner.revision===sessionRevision()}
/** 读取个人场景，不访问管理员模板配置。 */
async function load(){if(!visible)return;const version=++readVersion;loading.value=true;error.value='';try{await init();if(!visible||version!==readVersion)return;if(!state.user){overview.value=null;return}const owner=session(),result=await getSubscriptions();if(visible&&same(owner)&&version===readVersion){const initial=!overview.value;overview.value=result;selected.value=subscriptionCandidates(result,initial?result.scenes.map(item=>item.scene):selected.value).map(item=>item.scene)}}catch(err){if(visible&&version===readVersion)error.value=errorMessage(err)}finally{if(version===readVersion)loading.value=false}}
/** 手动选择只改变本次申请，最多三个不同模板；不写任何授权额度。 */
function toggleSelection(scene:SubscriptionScene){if(busy.value)return;if(selected.value.includes(scene)){selected.value=selected.value.filter(item=>item!==scene);return}const next=[...selected.value,scene],templates=new Set((overview.value?.scenes||[]).filter(item=>next.includes(item.scene)&&item.available&&item.enabled&&item.template_id).map(item=>item.template_id));if(templates.size>3)return notify('每次最多申请三个不同模板，请先取消一项');if(subscriptionCandidates(overview.value,next).some(item=>item.scene===scene))selected.value=next}
/** 用户偏好按单场景更新，服务端权限仍为准。 */
async function setPreference(scene:SubscriptionScene,value:boolean){if(!visible||busy.value||!state.user)return;const owner=session(),version=++operation;busy.value=true;error.value='';try{const result=await updateSubscriptionPreferences({[scene]:value});if(visible&&same(owner)&&version===operation){overview.value=result;if(!value)selected.value=selected.value.filter(item=>item!==scene)}}catch(err){if(visible&&same(owner)&&version===operation)error.value=errorMessage(err)}finally{if(version===operation)busy.value=false}}
/** 必须在用户按钮点击栈内调用原生 API，之后才等待和保存真实结果。 */
async function subscribe(){if(!visible||busy.value||loading.value||!selectedCandidates.value.length)return;const owner=session(),version=++operation;busy.value=true;error.value='';try{const pending=requestSubscriptionFromGesture(overview.value,selected.value,wechatSubscribeAPI()),result=await pending;if(!same(owner)||version!==operation)return;await recordSubscriptionAuthorization(result);if(visible&&same(owner)&&version===operation)notify(result.results.some(item=>item.status==='accept')?'本次订阅选择已记录':'未订阅成功，不影响正常使用')}catch(err){if(visible&&same(owner)&&version===operation)error.value=errorMessage(err)}finally{if(version===operation)busy.value=false}}
/** 换号撤销个人场景与旧操作，不在本地持久化配置。 */
function clear(){readVersion++;operation++;overview.value=null;selected.value=[];loading.value=false;busy.value=false;error.value=''}
watch([()=>state.user?.id,sessionRevision],()=>{clear();if(visible)void load()},{flush:'sync'})
useNativePageRefresh({refresh:load,context:()=>[state.user?.id,state.user?.role,sessionRevision()],blocked:()=>busy.value})
onShow(()=>{visible=true;void load()});onHide(()=>{visible=false;readVersion++;loading.value=false});onUnload(()=>{disposed=true;clear()})
</script>
<style scoped>
.subscription-intro{display:flex;align-items:center;gap:23.0769rpx;margin:15.3846rpx 0 46.1538rpx;min-width:0}.subscription-intro-icon{display:flex;align-items:center;justify-content:center;flex-shrink:0;width:100rpx;height:100rpx;border-radius:50%;color:var(--accent);background:var(--surface)}.subscription-intro-copy,.subscription-row-copy{flex:1;min-width:0}.subscription-intro-title{display:block;font-size:32.6923rpx;font-weight:650;line-height:50rpx;overflow-wrap:anywhere}.subscription-muted{display:block;font-size:23.0769rpx;line-height:38.4615rpx;color:var(--muted);overflow-wrap:anywhere}.subscription-section-title{display:block;font-size:25rpx;line-height:42.3077rpx;color:var(--muted);padding-bottom:15.3846rpx;border-bottom:1px solid var(--line-subtle)}.subscription-row{display:flex;align-items:center;gap:23.0769rpx;padding:23.0769rpx 0;border-bottom:1px solid var(--line-subtle);min-width:0}.subscription-label{display:block;font-size:28.8462rpx;line-height:46.1538rpx;font-weight:600}.subscription-unavailable,.subscription-notice{display:block;color:#dfbb71;font-size:23.0769rpx;line-height:38.4615rpx;overflow-wrap:anywhere}.subscription-choice{display:flex;align-items:center;gap:7.6923rpx;color:var(--muted);font-size:23.0769rpx;min-height:69.2308rpx}.subscription-authorize{margin-top:38.4615rpx;width:100%}.subscription-footnote{display:block;font-size:21.1538rpx;line-height:36.5385rpx;color:var(--muted);margin-top:15.3846rpx;overflow-wrap:anywhere}.subscription-error{display:flex;flex-direction:column;gap:15.3846rpx}
</style>
